{
  "schema": "pv-station-pollution-detect-config",
  "version": "1.0",
  "description": "光伏电站逐小时时序数据 9 类污染检测的阈值与响应规则配置清单，与 pv-station-analysis skill 的 scripts/pollution_detect.py 配套使用（基线来自 30.542/101.948 站点 2005-2023 数据集验证结果）",
  "data_format": {
    "source": "PVGIS-ERA5 逐小时 CSV（含 time, P, Gb(i), Gd(i), Gr(i), H_sun, T2m, WS10m, Int 列）",
    "nominal_system_kwp": 1.0,
    "nominal_power_w_hard_cap": 2500,
