      "id": "reconstructed",
      "name": "重建 / 插值标记",
      "category": "数据来源标记",
      "enabled": true,
      "severity": "medium",
      "thresholds": {},
      "trigger_rule": "数据源插值/重建标记列 Int != 0 的行即视为重建数据",
      "response": {
        "alert": "检出重建行（x 行，Int!=0），重建值可能偏离真实量测",
        "data_quality_verdict": "poor - 需清洗"
      },
