    },
    {
      "id": "stuck",
      "name": "卡死段",
      "category": "传感器 / 采集冻结",
      "enabled": true,
      "severity": "high",
      "thresholds": {
        "min_hours": 6,
        "day_start_hour": 7,
        "day_end_hour": 18,
